CREATE TABLE commands(id VARCHAR(100) PRIMARY KEY,request_hash VARCHAR(64) NOT NULL,response TEXT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE jobs(id VARCHAR(36) PRIMARY KEY,customer VARCHAR(180) NOT NULL,vehicle VARCHAR(180) NOT NULL,registration VARCHAR(50) NOT NULL,phone VARCHAR(50) NOT NULL,summary VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE processed_events(id VARCHAR(36) PRIMARY KEY,payload_hash VARCHAR(64) NOT NULL);
CREATE TABLE allocations(id VARCHAR(36) PRIMARY KEY,job_id VARCHAR(36) NOT NULL,product_id VARCHAR(36) NOT NULL,sku VARCHAR(80) NOT NULL,name VARCHAR(180) NOT NULL,unit VARCHAR(10) NOT NULL,kind VARCHAR(20) NOT NULL,quantity DECIMAL(18,3) NOT NULL,unit_price DECIMAL(18,2) NOT NULL,issue_id VARCHAR(36),created_at VARCHAR(40) NOT NULL);
CREATE TABLE invoices(id VARCHAR(36) PRIMARY KEY,job_id VARCHAR(36) NOT NULL UNIQUE REFERENCES jobs(id),invoice_number VARCHAR(60) NOT NULL UNIQUE,snapshot TEXT NOT NULL,labour DECIMAL(18,2) NOT NULL,total DECIMAL(18,2) NOT NULL,revision BIGINT NOT NULL,created_at VARCHAR(40) NOT NULL,approved_by VARCHAR(180) NOT NULL);
